Library IEEE;use IEEE.Std_Logic_1164.all;entity Prob_8_40 is	port (Data_out: out Std_Logic_vector (7 downto 0); 	Ready, Got_Data, Done_Product: out Std_Logic; 	Data_in: in Std_Logic_vector (7 downto 0); 	Start, Run, Send_Data, clock, reset_b: in Std_Logic);end Prob_8_40;architecture Behavior of Prob_8_40 issignal Load_P, Shift_in, Shift_out, Shift_regs, Add_regs, Decr_P, Zero, Q0: Std_Logic;component Controller port (Ready, Load_P, Shift_in, Got_Data, Done_Product, Decr_P, Add_regs,       Shift_regs, Shift_out: out Std_Logic; Start, Run, Send_Data, Zero, Q0, 	clock, reset_b: in Std_Logic);end component;component Datapath 	generic  dp_width: integer := 32; P_width: integer := 6);	port (Data_out: out Std_Logic_vector (7 downto 0);  			Q0, Zero: out Std_Logic;  			Data_in: in Std_Logic_vector (7 downto 0);  			Start, Shift_in, Load_P, Decr_P, Add_regs, Shift_regs, Shift_out, clock: in std_Logic);end component;beginM0: Controller port map (Ready, Load_P, Shift_in, Got_Data, Done_Product, Decr_P, Add_regs,       Shift_regs, Shift_out, Start, Run, Send_Data, Zero, Q0, clock, reset_b); M1: Datapath generic map (dp_width => 32, P_width => 6)port map (Data_out, Q0, Zero, Data_in, Start, Shift_in, Load_P, Decr_P, Add_regs, Shift_regs, Shift_out, clock);	end Behavior;Library IEEE;use IEEE.Std_Logic_1164.all;entity Controller is 	port (	Ready, Load_P, Shift_in, Got_Data, Done_Product, Decr_P, Add_regs,       Shift_regs, Shift_out: out Std_Logic; 	Start, Run, Send_Data, Zero, Q0, clock, reset_b: in Std_Logic);end Controller;architecture Behavioral of Controller is	constant		S_idle: Std_Logic_vector (4 downto 0)		:= "10100"; 	constant		S_Ld_0: Std_Logic_vector (4 downto 0)		:= "00000";	constant		S_Ld_1: Std_Logic_vector (4 downto 0)		:= "00001";	constant		S_Ld_2: Std_Logic_vector (4 downto 0)		:= "00010";	constant		S_Ld_3: Std_Logic_vector (4 downto 0)		:= "00011";	constant		S_Ld_4: Std_Logic_vector (4 downto 0)		:= "00100";	constant		S_Ld_5: Std_Logic_vector (4 downto 0)		:= "00101";	constant		S_Ld_6: Std_Logic_vector (4 downto 0)		:= "00110";	constant		S_Ld_7: Std_Logic_vector (4 downto 0)		:= "00111";	constant		S_wait_1: Std_Logic_vector (4 downto 0)	:= "01000";	-- wait state	constant		S_add: 	Std_Logic_vector (4 downto 0)	:= "01001";	constant		S_shift: 	Std_Logic_vector (4 downto 0)	:= "01010";	constant		S_product: Std_Logic_vector (4 downto 0)	:= "01011";	constant		S_wait_2: Std_Logic_vector (4 downto 0)	:= "11000";	constant		S_send_0: Std_Logic_vector (4 downto 0)	:= "01101";	-- wait state	constant		S_send_1: Std_Logic_vector (4 downto 0)	:= "01110";	constant		S_send_2: Std_Logic_vector (4 downto 0)	:= "01111";		 	constant		S_send_3: Std_Logic_vector (4 downto 0)	:= "10000";					constant		S_send_4: Std_Logic_vector (4 downto 0)	:= "10001";			constant		S_send_5: Std_Logic_vector (4 downto 0)	:= "10010";		 	constant		S_send_6: Std_Logic_vector (4 downto 0)	:= "10011";			 	signal	state, next_state: Std_Logic_vector (4 downto 0);begin	process (clock, reset_b) begin   		if reset_b = '0' then state <= S_idle; 		elsif clock'event and clock = '1' then  state <= next_state; 		end if;	end process;  	process (state, Start, Run, Q0, Zero, Send_Data) begin    		next_state 		<= S_idle;	-- Initialize for assignment   		Ready 				<= '0';		-- by exception    		Shift_in 			<= '0';    		Shift_regs 			<= '0';    		Add_regs 			<= '0';		Load_P 			<= '0';    		Decr_P 			<= '0';    		Shift_out 			<= '0';   		Got_Data 			<=' 0';    		Done_Product		<= '0';	case (state) is	      when S_idle =>	Ready <= '1'; 			       	  	if (Start = '1')  then 							next_state <= S_Ld_0; 							Shift_in <= '1'; 							Load_P <= '1';						end if;      when S_Ld_0 =>		 next_state <= S_Ld_1; Shift_in <= '1';			 	      when S_Ld_1 =>		 next_state <= S_Ld_2; Shift_in <= '1';       when S_Ld_2 =>		 next_state <= S_Ld_3; Shift_in <= '1';       when S_Ld_3 =>		 next_state <= S_Ld_4; Shift_in <= '1';	      when S_Ld_4 =>		 next_state <= S_Ld_5; Shift_in <= '1';       when S_Ld_5 =>		 next_state <= S_Ld_6; Shift_in <= '1';       when S_Ld_6 =>		 next_state <= S_Ld_7; Shift_in <= '1';	      when S_Ld_7 =>		 Got_Data <= '1';  			  		  		if (Run = '1') then next_state <= S_add; 			  		  		else next_state <= S_wait_1;							end if;      when S_wait_1 =>	if (Run = '1') then next_state <= S_add; 							else next_state <= S_wait_1;      when S_add =>		next_state <= S_Shift; Decr_P <= '1'; 							if (Q0 = '1') then Add_regs <= '1'; end if;      when S_Shift =>		Shift_regs <= '1'; 							if (Zero = '1') then next_state <= S_product; 							else next_state <= S_add; end if;      when S_product =>	 					  		Done_Product <= '1'; 					  		if (Send_Data = '1')   then 								next_state <= S_Send_0; 								Shift_out <= '1'; 					  		else next_state <= S_wait_2; 							end if;      when S_wait_2 =>	if (Send_Data = '1')  then								next_state <=S_Send_0; Shift_out <= '1'; 							else next_state <= S_wait_2;							end if;      when S_Send_0 =>	 next_state <= S_Send_1; Shift_out <= '1';         when S_Send_1 =>	 next_state <= S_Send_2; Shift_out <= '1';         when S_Send_2 =>	 next_state <= S_Send_3; Shift_out <= '1';         when S_Send_3 =>	 next_state <= S_Send_4; Shift_out <= '1';          when S_Send_4 =>	 next_state <= S_Send_5; Shift_out <= '1';         when S_Send_5 =>	 next_state <= S_Send_6; Shift_out <= '1';        when S_Send_6 =>	 next_state <= S_idle; Shift_out <= '1';         when others =>		next_state <= S_idle;    end case;  end process;end Behavioral;Library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Unsigned.allentity Datapath is	generic (dp_width: integer := 32; P_width: integer := 6);	port (	Data_out: out Std_Logic_vector (7 downto 0); 	Q0, Zero: out Std_Logic; 	Data_in: in Std_Logic_vector (7 downto 0);	Start, Shift_in, Load_P, Decr_P, Add_regs, Shift_regs, Shift_out, clock: in Std_Logic	);end Datapath;architecture Behavioral of Datapath is	signal	A, B, Q:	Std_Logic_vector	(dp_width - 1 downto 0);		-- Sized for datapath	signal	C: Std_Logic;	signal	P: integer;	signal sum: Std_Logic_vector (dp_width downto 0);begin	Q0 <= Q(0);		Zero <= '1' when P = 0 else '0';			-- counter is zero	Data_out <= Q(7 downto 0);	sum <= ('0' & A) + ('0' & B); 	-- Note: sum includes carry bit; bytes of Q arrive first	process (clock) begin		if Load_P = '1' then P <= dp_width; end if;		if (Shift_in = '1') then  -- Load pipe registers with data		for k in 0 to dp_width-1 loop A(k) <= '0'; end loop; 	-- A <= 0;			C <= '0';      		B(7 downto 0) 	<= B(15 downto 8);		--Treat B and Q registers as a       		B(15 downto 8) 	<= B( 23 downto 16);	-- pipeline to load data bytes			B(23 downto 16) 	<= B(31 downto 24);      		B(31 downto 24) 	<= Q(7 downto 0);      		Q(7 downto 0) 	<= Q(15 downto 8);      		Q(15 downto 8) 	<= Q( 23 downto 16);      		Q(23 downto 16)	<= Q(31 downto 24);      		Q(31 downto 24) 	<= Data_in;		end if;		if (Add_regs = '1') then 			C <= sum (dp_width);			A < sum(dp_width-1 downto 0); 		end if;    		if (Shift_regs = '1') then 	-- Data_out <= (C & A & Q) srl 1; 								C <= '0';								A <= C & A(dp_width-1 downto 1);								Q <= A(0) & Q(dp_with-1 downto 1);		 end if;    		if (Decr_P = '1') then P <= P -1; end if;    		if (Shift_out = '1') then 	 			C <= '0';			Q(7 downto 0) <= Q(15 downto 8);			Q(15 downto 8) <= Q(23 downto 16);			Q(23 downto 16) <= Q(31 downto 24);			Q(31 downto 24) <= A(7 downto 0);			A(7 downto 0) <= A(15 downto 8);			A(15 downto 8) <= A(23 downto 16);			A(23 downto 16) <= A(31 downto 24)			A(31 downto 24) <= "0000000" & C;		end if;	end process;												 end Behavioral; 